#include "PayloadImage.h"

#include <cstdint>
#include <cstring>

// Generated by mkpayload.py from the payload's ELF
#include "payload_layout.h"

bool PayloadImage::open(const char* filename) {
    romAddress = dfs_rom_addr(filename);

    if (romAddress == 0) {
        debugf("[PayloadImage] Payload doesn't exist! %s\n", filename);
        return false;
    }

    return true;
}

void PayloadImage::place(uint32_t capacity) {
    imageBase = 0;
    imageSize = 0;

    if (!isOpen()) {
        return;
    }

    if (!is_memory_expanded()) {
        debugf("[PayloadImage] Expansion Pak required to load the payload\n");
        return;
    }

    assertf(
        PAYLOAD_IMAGE_SIZE <= capacity,
        "Payload image (0x%08x to 0x%08x) is over 0x%lx bytes",
        PAYLOAD_IMAGE_BASE, PAYLOAD_IMAGE_BASE + PAYLOAD_IMAGE_SIZE, capacity
    );

    uint8_t* base = (uint8_t*)PAYLOAD_IMAGE_BASE;

    // The BSS, past the file's bytes. Through the cache, which the write-back
    // before the DMA below empties.
    memset(base + PAYLOAD_IMAGE_FILE_SIZE, 0, PAYLOAD_IMAGE_SIZE - PAYLOAD_IMAGE_FILE_SIZE);

    data_cache_hit_writeback_invalidate(base, PAYLOAD_IMAGE_SIZE);   /* before DMA */
    dma_read(base, romAddress, PAYLOAD_IMAGE_FILE_SIZE);

    // It's run as code
    inst_cache_hit_invalidate(base, PAYLOAD_IMAGE_SIZE);

    imageBase = PAYLOAD_IMAGE_BASE;
    imageSize = PAYLOAD_IMAGE_SIZE;

    debugf("[PayloadImage] Placed payload image (0x%lx bytes at 0x%08lx)\n", imageSize, imageBase);
}
